review_case_hold_shape_ck.value:
(
        (
          "review_case"."evidenced_state" = 'hold'
          AND "review_case"."hold_reason" ~ '^[a-z][a-z0-9_:-]{0,127}$'
        )
        OR (
          "review_case"."evidenced_state" <> 'hold'
          AND "review_case"."hold_reason" IS NULL
        )
      ) IS TRUE
